# -*- coding: utf-8 -*-
"""Complete set of 16 simulators for Class 3 Mathematics Chapter 5: Fun with Shapes."""

simulators = {
    'sim_rangoli_dot_grid': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 1</span>\n            <h3 class="text-lg font-bold text-slate-100">Courtyard Rangoli Dot Grid</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-amber-500/20 text-amber-300 font-semibold border border-amber-500/30">Dot Grid Geometry</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Connect evenly spaced dots on this traditional courtyard floor to construct squares, triangles, and smooth circular loops!\n    </p>\n\n    <!-- Canvas Container -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="rangoliSvg" viewBox="0 0 360 220" class="w-full max-w-[420px] h-48 select-none bg-radial from-slate-900 to-slate-950 rounded-lg shadow-inner">\n            <!-- Background grid lines -->\n            <defs>\n                <pattern id="dotPattern" width="40" height="40" patternUnits="userSpaceOnUse">\n                    <circle cx="20" cy="20" r="2.5" fill="#64748b" opacity="0.6"/>\n                </pattern>\n            </defs>\n            <rect width="360" height="220" fill="url(#dotPattern)" />\n\n            <!-- Dynamic Shapes Group -->\n            <g id="rangoliShapesGroup">\n                <!-- Squares -->\n                <rect id="rgSquare" x="60" y="60" width="80" height="80" fill="rgba(245, 158, 11, 0.15)" stroke="#f59e0b" stroke-width="3" stroke-dasharray="0" class="transition-all duration-300"/>\n                <!-- Triangles -->\n                <polygon id="rgTriangle" points="260,60 220,140 300,140" fill="rgba(16, 185, 129, 0.15)" stroke="#10b981" stroke-width="3" class="transition-all duration-300"/>\n                <!-- Circular Loops -->\n                <circle id="rgCircle" cx="180" cy="100" r="35" fill="rgba(59, 130, 246, 0.15)" stroke="#3b82f6" stroke-width="3" stroke-dasharray="4 2" class="transition-all duration-300"/>\n            </g>\n\n            <!-- Guide Labels -->\n            <text id="rgSqLabel" x="100" y="105" fill="#fbbf24" font-size="11" font-weight="bold" text-anchor="middle">Square</text>\n            <text id="rgTriLabel" x="260" y="115" fill="#34d399" font-size="11" font-weight="bold" text-anchor="middle">Triangle</text>\n            <text id="rgCirLabel" x="180" y="105" fill="#60a5fa" font-size="11" font-weight="bold" text-anchor="middle">Circle Loop</text>\n        </svg>\n\n        <div id="rangoliShapeInfo" class="mt-2 text-xs text-amber-300 font-semibold bg-amber-950/40 px-3 py-1.5 rounded-lg border border-amber-800/40 text-center w-full">\n            ✨ Showing all foundational rangoli elements: 1 Square (4 straight sides), 1 Triangle (3 straight sides), and 1 Circular Arc (continuous curve).\n        </div>\n    </div>\n\n    <!-- Controls -->\n    <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 pt-1">\n        <button onclick="toggleRangoliElement(\'square\')" class="px-3 py-2 rounded-xl bg-amber-500/20 hover:bg-amber-500/30 text-amber-300 border border-amber-500/40 text-xs font-bold transition flex items-center justify-center gap-1.5">\n            <span>■ Square (4 Sides)</span>\n        </button>\n        <button onclick="toggleRangoliElement(\'triangle\')" class="px-3 py-2 rounded-xl bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-300 border border-emerald-500/40 text-xs font-bold transition flex items-center justify-center gap-1.5">\n            <span>▲ Triangle (3 Sides)</span>\n        </button>\n        <button onclick="toggleRangoliElement(\'circle\')" class="px-3 py-2 rounded-xl bg-blue-500/20 hover:bg-blue-500/30 text-blue-300 border border-blue-500/40 text-xs font-bold transition flex items-center justify-center gap-1.5">\n            <span>● Circle (Curve)</span>\n        </button>\n        <button onclick="resetRangoliElements()" class="px-3 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700 text-xs font-bold transition flex items-center justify-center gap-1.5">\n            <span>🔄 Show All</span>\n        </button>\n    </div>\n</div>\n\n<script>\nwindow.rgState = { square: true, triangle: true, circle: true };\n\nwindow.toggleRangoliElement = function(type) {\n    window.rgState[type] = !window.rgState[type];\n    updateRangoliDisplay();\n};\n\nwindow.resetRangoliElements = function() {\n    window.rgState = { square: true, triangle: true, circle: true };\n    updateRangoliDisplay();\n};\n\nfunction updateRangoliDisplay() {\n    const sq = document.getElementById(\'rgSquare\');\n    const sql = document.getElementById(\'rgSqLabel\');\n    const tr = document.getElementById(\'rgTriangle\');\n    const trl = document.getElementById(\'rgTriLabel\');\n    const cr = document.getElementById(\'rgCircle\');\n    const crl = document.getElementById(\'rgCirLabel\');\n    const info = document.getElementById(\'rangoliShapeInfo\');\n\n    if (sq) sq.style.display = window.rgState.square ? \'block\' : \'none\';\n    if (sql) sql.style.display = window.rgState.square ? \'block\' : \'none\';\n    if (tr) tr.style.display = window.rgState.triangle ? \'block\' : \'none\';\n    if (trl) trl.style.display = window.rgState.triangle ? \'block\' : \'none\';\n    if (cr) cr.style.display = window.rgState.circle ? \'block\' : \'none\';\n    if (crl) crl.style.display = window.rgState.circle ? \'block\' : \'none\';\n\n    let parts = [];\n    if (window.rgState.square) parts.push(\'Square (4 equal sides, 4 corners)\');\n    if (window.rgState.triangle) parts.push(\'Triangle (3 straight sides, 3 corners)\');\n    if (window.rgState.circle) parts.push(\'Circle (smooth curved boundary, 0 corners)\');\n\n    if (parts.length === 0) {\n        info.innerHTML = "Canvas cleared. Click any button above to draw geometric shapes on the dot grid!";\n    } else {\n        info.innerHTML = "Active Elements: " + parts.join(" • ");\n    }\n}\n</script>\n',
    'sim_lines_and_curves': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 2</span>\n            <h3 class="text-lg font-bold text-slate-100">Straight Edges vs Curved Lines</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-emerald-500/20 text-emerald-300 font-semibold border border-emerald-500/30">Edge Classification</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Test everyday household objects to determine whether their boundaries are formed by straight edges, curved lines, or both!\n    </p>\n\n    <!-- Interactive Classification Stage -->\n    <div class="grid grid-cols-1 md:grid-cols-3 gap-3">\n        <!-- Pure Straight Category -->\n        <div class="bg-slate-950/80 border border-indigo-500/40 rounded-xl p-3 flex flex-col items-center">\n            <span class="text-xs font-bold uppercase text-indigo-400 tracking-wider mb-2">Straight Lines Only</span>\n            <div id="straightItemsList" class="space-y-1.5 w-full min-h-[90px]">\n                <div class="text-[11px] bg-indigo-950/60 border border-indigo-700/50 rounded-lg p-2 text-indigo-200 flex items-center justify-between">\n                    <span>📏 Wooden Ruler</span>\n                    <span class="text-[10px] text-indigo-400 font-mono">4 Straight</span>\n                </div>\n                <div class="text-[11px] bg-indigo-950/60 border border-indigo-700/50 rounded-lg p-2 text-indigo-200 flex items-center justify-between">\n                    <span>🥪 Sandwich Slice</span>\n                    <span class="text-[10px] text-indigo-400 font-mono">3 Straight</span>\n                </div>\n            </div>\n            <span class="text-[10px] text-slate-400 mt-2 font-mono">Meet at Sharp Corners</span>\n        </div>\n\n        <!-- Pure Curved Category -->\n        <div class="bg-slate-950/80 border border-emerald-500/40 rounded-xl p-3 flex flex-col items-center">\n            <span class="text-xs font-bold uppercase text-emerald-400 tracking-wider mb-2">Curved Lines Only</span>\n            <div id="curvedItemsList" class="space-y-1.5 w-full min-h-[90px]">\n                <div class="text-[11px] bg-emerald-950/60 border border-emerald-700/50 rounded-lg p-2 text-emerald-200 flex items-center justify-between">\n                    <span>⭕ Glass Bangle</span>\n                    <span class="text-[10px] text-emerald-400 font-mono">0 Corners</span>\n                </div>\n                <div class="text-[11px] bg-emerald-950/60 border border-emerald-700/50 rounded-lg p-2 text-emerald-200 flex items-center justify-between">\n                    <span>🪙 Rupee Coin</span>\n                    <span class="text-[10px] text-emerald-400 font-mono">Continuous</span>\n                </div>\n            </div>\n            <span class="text-[10px] text-slate-400 mt-2 font-mono">Zero Sharp Corners</span>\n        </div>\n\n        <!-- Hybrid Category -->\n        <div class="bg-slate-950/80 border border-amber-500/40 rounded-xl p-3 flex flex-col items-center">\n            <span class="text-xs font-bold uppercase text-amber-400 tracking-wider mb-2">Both Straight & Curved</span>\n            <div id="bothItemsList" class="space-y-1.5 w-full min-h-[90px]">\n                <div class="text-[11px] bg-amber-950/60 border border-amber-700/50 rounded-lg p-2 text-amber-200 flex items-center justify-between">\n                    <span>🍦 Ice Cream Cone</span>\n                    <span class="text-[10px] text-amber-400 font-mono">2 Slant + 1 Arc</span>\n                </div>\n                <div class="text-[11px] bg-amber-950/60 border border-amber-700/50 rounded-lg p-2 text-amber-200 flex items-center justify-between">\n                    <span>🚪 Arched Doorway</span>\n                    <span class="text-[10px] text-amber-400 font-mono">3 Flat + 1 Arch</span>\n                </div>\n            </div>\n            <span class="text-[10px] text-slate-400 mt-2 font-mono">Composite Contours</span>\n        </div>\n    </div>\n\n    <!-- Live Test Button -->\n    <div class="bg-slate-950 p-3 rounded-xl border border-slate-800 flex flex-col sm:flex-row items-center justify-between gap-3">\n        <div class="flex items-center gap-2">\n            <span class="text-xs text-slate-400">Current Test Item:</span>\n            <span id="currentItemName" class="text-xs font-bold text-amber-300 bg-amber-500/10 px-2 py-0.5 rounded border border-amber-500/30">Matchbox (Cuboid Face)</span>\n        </div>\n        <div class="flex gap-2">\n            <button onclick="cycleLineTestItem()" class="px-3 py-1.5 bg-indigo-600 hover:bg-indigo-500 rounded-lg text-xs font-bold transition">\n                🔀 Test Next Item\n            </button>\n        </div>\n    </div>\n</div>\n\n<script>\nwindow.testItems = [\n    { name: "Matchbox (Top Face)", category: "Straight Lines Only", desc: "4 straight segments meeting at 4 right angles." },\n    { name: "Dinner Plate Rim", category: "Curved Lines Only", desc: "Smooth circular rim with zero vertices or corners." },\n    { name: "Watermelon Slice", category: "Both Straight & Curved", desc: "2 straight radiating cuts meeting at a point + 1 curved rind arc." },\n    { name: "Book Spine & Cover", category: "Straight Lines Only", desc: "Bounded by straight perpendicular edges." },\n    { name: "Bicycle Wheel Rim", category: "Curved Lines Only", desc: "Pure circular curved boundary rolling without bumping." }\n];\nwindow.currItemIdx = 0;\n\nwindow.cycleLineTestItem = function() {\n    window.currItemIdx = (window.currItemIdx + 1) % window.testItems.length;\n    const itm = window.testItems[window.currItemIdx];\n    const lbl = document.getElementById(\'currentItemName\');\n    if (lbl) {\n        lbl.innerText = itm.name + " (" + itm.category + ")";\n    }\n};\n</script>\n',
    'sim_shape_cutout_art': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 3</span>\n            <h3 class="text-lg font-bold text-slate-100">Composite Shape Cutout Art</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-cyan-500/20 text-cyan-300 font-semibold border border-cyan-500/30">Composite Geometry</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Combine pre-cut squares, triangles, rectangles, and circles to assemble real-world figures without drawing lines!\n    </p>\n\n    <!-- Art Canvas Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="cutoutCanvasSvg" viewBox="0 0 360 180" class="w-full max-w-[420px] h-44 bg-slate-900 rounded-lg shadow-inner">\n            <g id="cutoutModelGroup">\n                <!-- Cottage (Default) -->\n                <!-- Roof: Green Triangle -->\n                <polygon points="180,30 110,80 250,80" fill="#10b981" stroke="#059669" stroke-width="2"/>\n                <!-- Wall: Red Square -->\n                <rect x="125" y="80" width="110" height="80" fill="#ef4444" stroke="#dc2626" stroke-width="2"/>\n                <!-- Door: Blue Rectangle -->\n                <rect x="160" y="110" width="40" height="50" fill="#3b82f6" stroke="#2563eb" stroke-width="2"/>\n                <!-- Windows: Yellow Squares -->\n                <rect x="135" y="95" width="20" height="20" fill="#facc15" stroke="#eab308" stroke-width="2"/>\n                <rect x="205" y="95" width="20" height="20" fill="#facc15" stroke="#eab308" stroke-width="2"/>\n                <!-- Chimney Smoke: Circles -->\n                <circle cx="230" cy="35" r="8" fill="#94a3b8" opacity="0.7"/>\n                <circle cx="238" cy="20" r="6" fill="#94a3b8" opacity="0.5"/>\n            </g>\n        </svg>\n\n        <div id="cutoutStats" class="mt-2 text-xs text-cyan-300 font-semibold bg-cyan-950/40 px-3 py-1.5 rounded-lg border border-cyan-800/40 text-center w-full">\n            🏡 Model: Village Cottage (1 Triangle + 3 Squares + 1 Rectangle + 2 Circles = 7 Cutouts)\n        </div>\n    </div>\n\n    <!-- Preset Model Buttons -->\n    <div class="grid grid-cols-3 gap-2">\n        <button onclick="loadCutoutModel(\'cottage\')" class="px-3 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 text-xs font-bold transition">\n            🏡 Cottage\n        </button>\n        <button onclick="loadCutoutModel(\'train\')" class="px-3 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 text-xs font-bold transition">\n            🚂 Toy Train\n        </button>\n        <button onclick="loadCutoutModel(\'sailboat\')" class="px-3 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 text-xs font-bold transition">\n            ⛵ Sailboat\n        </button>\n    </div>\n</div>\n\n<script>\nwindow.loadCutoutModel = function(model) {\n    const grp = document.getElementById(\'cutoutModelGroup\');\n    const stats = document.getElementById(\'cutoutStats\');\n    if (!grp) return;\n\n    if (model === \'cottage\') {\n        grp.innerHTML = `\n            <polygon points="180,30 110,80 250,80" fill="#10b981" stroke="#059669" stroke-width="2"/>\n            <rect x="125" y="80" width="110" height="80" fill="#ef4444" stroke="#dc2626" stroke-width="2"/>\n            <rect x="160" y="110" width="40" height="50" fill="#3b82f6" stroke="#2563eb" stroke-width="2"/>\n            <rect x="135" y="95" width="20" height="20" fill="#facc15" stroke="#eab308" stroke-width="2"/>\n            <rect x="205" y="95" width="20" height="20" fill="#facc15" stroke="#eab308" stroke-width="2"/>\n            <circle cx="230" cy="35" r="8" fill="#94a3b8" opacity="0.7"/>\n            <circle cx="238" cy="20" r="6" fill="#94a3b8" opacity="0.5"/>\n        `;\n        stats.innerText = "🏡 Model: Village Cottage (1 Triangle + 3 Squares + 1 Rectangle + 2 Circles = 7 Cutouts)";\n    } else if (model === \'train\') {\n        grp.innerHTML = `\n            <rect x="80" y="60" width="80" height="70" fill="#3b82f6" stroke="#2563eb" stroke-width="2"/>\n            <rect x="160" y="90" width="120" height="40" fill="#ef4444" stroke="#dc2626" stroke-width="2"/>\n            <rect x="95" y="70" width="25" height="25" fill="#facc15" stroke="#eab308" stroke-width="2"/>\n            <rect x="240" y="70" width="20" height="20" fill="#10b981" stroke="#059669" stroke-width="2"/>\n            <circle cx="105" cy="140" r="14" fill="#64748b" stroke="#334155" stroke-width="3"/>\n            <circle cx="145" cy="140" r="14" fill="#64748b" stroke="#334155" stroke-width="3"/>\n            <circle cx="190" cy="140" r="14" fill="#64748b" stroke="#334155" stroke-width="3"/>\n            <circle cx="250" cy="140" r="14" fill="#64748b" stroke="#334155" stroke-width="3"/>\n        `;\n        stats.innerText = "🚂 Model: Toy Train (3 Rectangles + 1 Square + 4 Circular Wheels = 8 Cutouts)";\n    } else if (model === \'sailboat\') {\n        grp.innerHTML = `\n            <polygon points="170,25 170,110 240,110" fill="#10b981" stroke="#059669" stroke-width="2"/>\n            <polygon points="160,40 160,110 110,110" fill="#06b6d4" stroke="#0891b2" stroke-width="2"/>\n            <line x1="165" y1="20" x2="165" y2="115" stroke="#78350f" stroke-width="3"/>\n            <polygon points="80,115 270,115 230,150 120,150" fill="#f59e0b" stroke="#d97706" stroke-width="2"/>\n            <circle cx="175" cy="132" r="6" fill="#ffffff" stroke="#94a3b8" stroke-width="1.5"/>\n        `;\n        stats.innerText = "⛵ Model: Sailboat (2 Sail Triangles + 1 Trapezoid Hull + 1 Circular Porthole = 4 Shapes)";\n    }\n};\n</script>\n',
    'sim_flattened_box_nets': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 4</span>\n            <h3 class="text-lg font-bold text-slate-100">Cardboard Box Net Unfolder</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-purple-500/20 text-purple-300 font-semibold border border-purple-500/30">3D to 2D Net</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Drag the unfold slider to flatten a 3D packaging carton into its 2D net of 6 connected rectangles!\n    </p>\n\n    <!-- Net Visualizer -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="boxNetSvg" viewBox="0 0 360 210" class="w-full max-w-[420px] h-48 bg-slate-900 rounded-lg shadow-inner">\n            <!-- 2D Net Representation -->\n            <!-- Central Column: Top (Face 1), Back (Face 2), Bottom (Face 3), Front (Face 4) -->\n            <!-- Left Wing: Left Face 5 | Right Wing: Right Face 6 -->\n            <g id="netRectangles" class="transition-all duration-300">\n                <!-- Face 1: Top -->\n                <rect x="140" y="15" width="80" height="40" fill="#a855f7" stroke="#9333ea" stroke-width="2" rx="2"/>\n                <text x="180" y="38" fill="#ffffff" font-size="10" font-weight="bold" text-anchor="middle">1. Top</text>\n\n                <!-- Face 2: Back -->\n                <rect x="140" y="60" width="80" height="40" fill="#3b82f6" stroke="#2563eb" stroke-width="2" rx="2"/>\n                <text x="180" y="83" fill="#ffffff" font-size="10" font-weight="bold" text-anchor="middle">2. Back</text>\n\n                <!-- Face 5: Left Flap -->\n                <rect id="leftFlap" x="55" y="60" width="80" height="40" fill="#10b981" stroke="#059669" stroke-width="2" rx="2"/>\n                <text id="leftFlapTxt" x="95" y="83" fill="#ffffff" font-size="10" font-weight="bold" text-anchor="middle">5. Left</text>\n\n                <!-- Face 6: Right Flap -->\n                <rect id="rightFlap" x="225" y="60" width="80" height="40" fill="#10b981" stroke="#059669" stroke-width="2" rx="2"/>\n                <text id="rightFlapTxt" x="265" y="83" fill="#ffffff" font-size="10" font-weight="bold" text-anchor="middle">6. Right</text>\n\n                <!-- Face 3: Bottom Base -->\n                <rect x="140" y="105" width="80" height="40" fill="#f59e0b" stroke="#d97706" stroke-width="2" rx="2"/>\n                <text x="180" y="128" fill="#ffffff" font-size="10" font-weight="bold" text-anchor="middle">3. Bottom</text>\n\n                <!-- Face 4: Front -->\n                <rect x="140" y="150" width="80" height="40" fill="#ef4444" stroke="#dc2626" stroke-width="2" rx="2"/>\n                <text x="180" y="173" fill="#ffffff" font-size="10" font-weight="bold" text-anchor="middle">4. Front</text>\n\n                <!-- Dashed Fold Creases -->\n                <line x1="140" y1="58" x2="220" y2="58" stroke="#cbd5e1" stroke-dasharray="3 3" stroke-width="1.5"/>\n                <line x1="140" y1="102" x2="220" y2="102" stroke="#cbd5e1" stroke-dasharray="3 3" stroke-width="1.5"/>\n                <line x1="140" y1="148" x2="220" y2="148" stroke="#cbd5e1" stroke-dasharray="3 3" stroke-width="1.5"/>\n                <line x1="138" y1="60" x2="138" y2="100" stroke="#cbd5e1" stroke-dasharray="3 3" stroke-width="1.5"/>\n                <line x1="222" y1="60" x2="222" y2="100" stroke="#cbd5e1" stroke-dasharray="3 3" stroke-width="1.5"/>\n            </g>\n        </svg>\n\n        <div id="netStatus" class="mt-2 text-xs text-purple-300 font-semibold bg-purple-950/40 px-3 py-1.5 rounded-lg border border-purple-800/40 text-center w-full">\n            📦 Unfolded Net: 6 Rectangular Faces (Top, Bottom, Front, Back, Left, Right)\n        </div>\n    </div>\n\n    <!-- Unfold Slider Controls -->\n    <div class="space-y-2 pt-1">\n        <div class="flex justify-between text-xs font-mono">\n            <span class="text-slate-400">Box Folding State:</span>\n            <span id="unfoldPctLabel" class="text-purple-400 font-bold">100% (Completely Flat Net)</span>\n        </div>\n        <input type="range" min="0" max="100" value="100" id="unfoldRange" oninput="updateBoxNetUnfold(this.value)" class="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-purple-500">\n        <div class="flex justify-between text-[11px] text-slate-500">\n            <span>0% (Assembled 3D Box)</span>\n            <span>50% (Partially Open)</span>\n            <span>100% (Flat 2D Net)</span>\n        </div>\n    </div>\n</div>\n\n<script>\nwindow.updateBoxNetUnfold = function(val) {\n    const lbl = document.getElementById(\'unfoldPctLabel\');\n    const lf = document.getElementById(\'leftFlap\');\n    const rf = document.getElementById(\'rightFlap\');\n    const lft = document.getElementById(\'leftFlapTxt\');\n    const rft = document.getElementById(\'rightFlapTxt\');\n    const st = document.getElementById(\'netStatus\');\n    const pct = parseInt(val);\n\n    if (lbl) lbl.innerText = pct + "% " + (pct === 100 ? "(Completely Flat Net)" : pct === 0 ? "(Closed 3D Box)" : "(Folding Creases)");\n\n    // Scale the wings to simulate 3D folding\n    const factor = pct / 100;\n    if (lf && rf) {\n        lf.setAttribute(\'width\', (80 * factor).toString());\n        lf.setAttribute(\'x\', (140 - (80 * factor) - 5).toString());\n        rf.setAttribute(\'width\', (80 * factor).toString());\n        if (lft) lft.setAttribute(\'x\', (140 - (40 * factor) - 5).toString());\n        if (rft) rft.setAttribute(\'x\', (225 + (40 * factor)).toString());\n    }\n\n    if (st) {\n        if (pct === 100) {\n            st.innerText = "📦 Unfolded Net: Exactly 6 rectangular faces laid flat along straight fold seams.";\n        } else if (pct === 0) {\n            st.innerText = "📦 Closed Box: Flaps join at right angles to enclose a hollow 3D volume.";\n        } else {\n            st.innerText = "📦 Transition: Flaps folding along crease lines to transform 2D into 3D.";\n        }\n    }\n};\n</script>\n',
    'sim_paper_fold_envelope': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 5</span>\n            <h3 class="text-lg font-bold text-slate-100">Origami Greeting Card Envelope</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-pink-500/20 text-pink-300 font-semibold border border-pink-500/30">Step-by-Step Folding</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Follow the sequential origami steps to transform a square sheet of craft paper into a functional greeting envelope!\n    </p>\n\n    <!-- Origami Visualizer -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="origamiSvg" viewBox="0 0 360 180" class="w-full max-w-[420px] h-44 bg-slate-900 rounded-lg shadow-inner">\n            <g id="origamiStepGroup">\n                <!-- Step 1: Flat Square Sheet -->\n                <rect x="110" y="20" width="140" height="140" fill="#f43f5e" stroke="#e11d48" stroke-width="2" rx="3"/>\n                <line x1="110" y1="20" x2="250" y2="160" stroke="#fecdd3" stroke-dasharray="4 3" stroke-width="1.5"/>\n                <text x="180" y="95" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">Square Sheet (4 Equal Sides)</text>\n            </g>\n        </svg>\n\n        <div id="origamiExplanation" class="mt-2 text-xs text-pink-300 font-semibold bg-pink-950/40 px-3 py-1.5 rounded-lg border border-pink-800/40 text-center w-full">\n            📄 Step 1 of 4: Start with a crisp square sheet of craft paper with 4 equal sides and 4 square corners.\n        </div>\n    </div>\n\n    <!-- Stepper Controls -->\n    <div class="flex items-center justify-between gap-3 pt-1">\n        <button onclick="changeOrigamiStep(-1)" class="px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-xl text-xs font-bold transition flex items-center gap-1">\n            <span>◀ Previous Fold</span>\n        </button>\n        <span id="origamiStepBadge" class="text-xs font-mono font-bold text-amber-400">Step 1 / 4</span>\n        <button onclick="changeOrigamiStep(1)" class="px-4 py-2 bg-pink-600 hover:bg-pink-500 rounded-xl text-xs font-bold transition flex items-center gap-1">\n            <span>Next Fold ▶</span>\n        </button>\n    </div>\n</div>\n\n<script>\nwindow.currOrigamiStep = 1;\n\nwindow.changeOrigamiStep = function(delta) {\n    window.currOrigamiStep += delta;\n    if (window.currOrigamiStep < 1) window.currOrigamiStep = 1;\n    if (window.currOrigamiStep > 4) window.currOrigamiStep = 4;\n    renderOrigami();\n};\n\nfunction renderOrigami() {\n    const grp = document.getElementById(\'origamiStepGroup\');\n    const exp = document.getElementById(\'origamiExplanation\');\n    const badge = document.getElementById(\'origamiStepBadge\');\n    if (!grp) return;\n\n    badge.innerText = "Step " + window.currOrigamiStep + " / 4";\n\n    if (window.currOrigamiStep === 1) {\n        grp.innerHTML = `\n            <rect x="110" y="20" width="140" height="140" fill="#f43f5e" stroke="#e11d48" stroke-width="2" rx="3"/>\n            <line x1="110" y1="20" x2="250" y2="160" stroke="#fecdd3" stroke-dasharray="4 3" stroke-width="1.5"/>\n            <text x="180" y="95" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">Square Sheet (4 Equal Sides)</text>\n        `;\n        exp.innerText = "📄 Step 1 of 4: Start with a crisp square sheet of craft paper with 4 equal sides and 4 square corners.";\n    } else if (window.currOrigamiStep === 2) {\n        grp.innerHTML = `\n            <polygon points="110,20 250,160 110,160" fill="#f43f5e" stroke="#e11d48" stroke-width="2"/>\n            <line x1="110" y1="20" x2="250" y2="160" stroke="#ffffff" stroke-width="2"/>\n            <text x="155" y="115" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">Diagonal Fold (2 Equal Triangles)</text>\n        `;\n        exp.innerText = "📐 Step 2 of 4: Crease diagonally across opposite corners to split the square into two symmetrical right triangles.";\n    } else if (window.currOrigamiStep === 3) {\n        grp.innerHTML = `\n            <rect x="110" y="60" width="140" height="90" fill="#be123c" stroke="#9f1239" stroke-width="2"/>\n            <polygon points="110,60 150,100 110,140" fill="#fb7185" stroke="#f43f5e" stroke-width="1.5"/>\n            <polygon points="250,60 210,100 250,140" fill="#fb7185" stroke="#f43f5e" stroke-width="1.5"/>\n            <polygon points="110,150 180,100 250,150" fill="#e11d48" stroke="#be123c" stroke-width="2"/>\n            <text x="180" y="135" fill="#ffffff" font-size="10" font-weight="bold" text-anchor="middle">Bottom Pocket + Side Flaps</text>\n        `;\n        exp.innerText = "✉️ Step 3 of 4: Fold side corners inward to center, then fold bottom flap upward to create a secure pocket.";\n    } else if (window.currOrigamiStep === 4) {\n        grp.innerHTML = `\n            <rect x="110" y="60" width="140" height="90" fill="#be123c" stroke="#9f1239" stroke-width="2" rx="3"/>\n            <polygon points="110,60 180,115 250,60" fill="#fb7185" stroke="#f43f5e" stroke-width="2"/>\n            <circle cx="180" cy="115" r="5" fill="#facc15" stroke="#eab308" stroke-width="1"/>\n            <text x="180" y="145" fill="#ffffff" font-size="10" font-weight="bold" text-anchor="middle">Completed Envelope (Sealed Flap)</text>\n        `;\n        exp.innerText = "💌 Step 4 of 4: Fold the top pointed triangular flap downward to seal your handsome greeting card envelope!";\n    }\n}\n</script>\n',
    'sim_biscuit_tray_arrays': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 6</span>\n            <h3 class="text-lg font-bold text-slate-100">Bakery Biscuit Tray Array</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-amber-500/20 text-amber-300 font-semibold border border-amber-500/30">Rows × Columns Array</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Adjust rows and columns on this metallic baking tray to see how identical biscuits pack into regular rectangular grids!\n    </p>\n\n    <!-- Baking Tray Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <div id="biscuitTrayGrid" class="bg-gradient-to-b from-stone-800 to-stone-900 border-4 border-stone-600 rounded-xl p-3 shadow-2xl flex flex-col gap-2 items-center justify-center min-h-[170px] w-full max-w-[400px]">\n            <!-- Dynamic rows of biscuits -->\n        </div>\n\n        <div id="trayMathBanner" class="mt-2 text-xs text-amber-300 font-semibold bg-amber-950/40 px-3 py-1.5 rounded-lg border border-amber-800/40 text-center w-full font-mono">\n            🧮 3 Rows × 4 Columns = 12 Delicious Golden Biscuits\n        </div>\n    </div>\n\n    <!-- Sliders -->\n    <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">\n        <div class="space-y-1">\n            <div class="flex justify-between text-xs font-mono">\n                <span class="text-slate-400">Horizontal Rows:</span>\n                <span id="trayRowsLbl" class="text-amber-400 font-bold">3 Rows</span>\n            </div>\n            <input type="range" min="1" max="5" value="3" id="trayRowsRange" oninput="updateBiscuitTray()" class="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-amber-500">\n        </div>\n\n        <div class="space-y-1">\n            <div class="flex justify-between text-xs font-mono">\n                <span class="text-slate-400">Vertical Columns:</span>\n                <span id="trayColsLbl" class="text-amber-400 font-bold">4 Columns</span>\n            </div>\n            <input type="range" min="1" max="6" value="4" id="trayColsRange" oninput="updateBiscuitTray()" class="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-amber-500">\n        </div>\n    </div>\n</div>\n\n<script>\nwindow.updateBiscuitTray = function() {\n    const rInput = document.getElementById(\'trayRowsRange\');\n    const cInput = document.getElementById(\'trayColsRange\');\n    const rLbl = document.getElementById(\'trayRowsLbl\');\n    const cLbl = document.getElementById(\'trayColsLbl\');\n    const grid = document.getElementById(\'biscuitTrayGrid\');\n    const banner = document.getElementById(\'trayMathBanner\');\n\n    if (!rInput || !cInput || !grid) return;\n\n    const rows = parseInt(rInput.value);\n    const cols = parseInt(cInput.value);\n    const total = rows * cols;\n\n    rLbl.innerText = rows + " Rows";\n    cLbl.innerText = cols + " Columns";\n    banner.innerText = "🧮 " + rows + " Rows × " + cols + " Columns = " + total + " Delicious Golden Biscuits";\n\n    grid.innerHTML = "";\n    for (let r = 0; r < rows; r++) {\n        const rowDiv = document.createElement(\'div\');\n        rowDiv.className = "flex gap-2 justify-center w-full";\n        for (let c = 0; c < cols; c++) {\n            const b = document.createElement(\'div\');\n            b.className = "w-9 h-7 rounded bg-amber-400 border border-amber-600 shadow-md flex items-center justify-center text-[10px] font-bold text-amber-950";\n            b.innerText = "🍪";\n            rowDiv.appendChild(b);\n        }\n        grid.appendChild(rowDiv);\n    }\n};\n// Initialize on load\nsetTimeout(function() { if (window.updateBiscuitTray) window.updateBiscuitTray(); }, 100);\n</script>\n',
    'sim_tracing_cuboid_faces': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 7</span>\n            <h3 class="text-lg font-bold text-slate-100">Tracing Cuboid 3D Faces</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-orange-500/20 text-orange-300 font-semibold border border-orange-500/30">3D to 2D Tracing</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Orient a wooden matchbox block on paper and trace its perimeter to reveal its three pairs of rectangular faces!\n    </p>\n\n    <!-- Tracing Paper Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="tracingSvg" viewBox="0 0 360 170" class="w-full max-w-[420px] h-44 bg-amber-50/10 rounded-lg border border-slate-800 shadow-inner">\n            <!-- Paper Sheet Background -->\n            <rect x="20" y="15" width="320" height="140" fill="#f8fafc" rx="4"/>\n\n            <!-- Traced Outlines -->\n            <!-- Large Face (Base) -->\n            <rect id="traceBase" x="40" y="35" width="90" height="60" fill="rgba(249, 115, 22, 0.2)" stroke="#ea580c" stroke-width="2" stroke-dasharray="3 3"/>\n            <text x="85" y="70" fill="#9a3412" font-size="9" font-weight="bold" text-anchor="middle">Base Face (9×6)</text>\n\n            <!-- Medium Face (Side Wall) -->\n            <rect id="traceSide" x="150" y="35" width="90" height="30" fill="rgba(59, 130, 246, 0.2)" stroke="#2563eb" stroke-width="2" stroke-dasharray="3 3"/>\n            <text x="195" y="53" fill="#1e40af" font-size="9" font-weight="bold" text-anchor="middle">Side Wall (9×3)</text>\n\n            <!-- Small Face (End Cap) -->\n            <rect id="traceEnd" x="260" y="35" width="60" height="30" fill="rgba(16, 185, 129, 0.2)" stroke="#059669" stroke-width="2" stroke-dasharray="3 3"/>\n            <text x="290" y="53" fill="#065f46" font-size="9" font-weight="bold" text-anchor="middle">End Face (6×3)</text>\n\n            <text x="180" y="125" fill="#475569" font-size="10" font-weight="bold" text-anchor="middle">A cuboid has 6 total faces: 3 pairs of matching rectangles!</text>\n        </svg>\n\n        <div id="tracingResultNotice" class="mt-2 text-xs text-orange-300 font-semibold bg-orange-950/40 px-3 py-1.5 rounded-lg border border-orange-800/40 text-center w-full">\n            ✏️ Current Orientation: Wide Base resting flat on paper, generating a 9 cm × 6 cm rectangle footprint.\n        </div>\n    </div>\n\n    <!-- Orientation Switcher -->\n    <div class="grid grid-cols-3 gap-2">\n        <button onclick="setTraceOrientation(\'base\')" class="px-3 py-2 bg-orange-500/20 hover:bg-orange-500/30 text-orange-300 border border-orange-500/40 rounded-xl text-xs font-bold transition">\n            1. Broad Base Face\n        </button>\n        <button onclick="setTraceOrientation(\'side\')" class="px-3 py-2 bg-blue-500/20 hover:bg-blue-500/30 text-blue-300 border border-blue-500/40 rounded-xl text-xs font-bold transition">\n            2. Long Side Edge\n        </button>\n        <button onclick="setTraceOrientation(\'end\')" class="px-3 py-2 bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-300 border border-emerald-500/40 rounded-xl text-xs font-bold transition">\n            3. Narrow End Cap\n        </button>\n    </div>\n</div>\n\n<script>\nwindow.setTraceOrientation = function(ori) {\n    const notice = document.getElementById(\'tracingResultNotice\');\n    const tb = document.getElementById(\'traceBase\');\n    const ts = document.getElementById(\'traceSide\');\n    const te = document.getElementById(\'traceEnd\');\n\n    if (ori === \'base\') {\n        if (tb) tb.setAttribute(\'stroke-width\', \'4\');\n        if (ts) ts.setAttribute(\'stroke-width\', \'1\');\n        if (te) te.setAttribute(\'stroke-width\', \'1\');\n        notice.innerText = "✏️ Broad Base: Large rectangular footprint (top and bottom matching pair).";\n    } else if (ori === \'side\') {\n        if (tb) tb.setAttribute(\'stroke-width\', \'1\');\n        if (ts) ts.setAttribute(\'stroke-width\', \'4\');\n        if (te) te.setAttribute(\'stroke-width\', \'1\');\n        notice.innerText = "✏️ Long Side: Medium elongated rectangle (front and back matching pair).";\n    } else if (ori === \'end\') {\n        if (tb) tb.setAttribute(\'stroke-width\', \'1\');\n        if (ts) ts.setAttribute(\'stroke-width\', \'1\');\n        if (te) te.setAttribute(\'stroke-width\', \'4\');\n        notice.innerText = "✏️ Narrow End: Small compact rectangle (left and right matching pair).";\n    }\n};\n</script>\n',
    'sim_dot_grid_rectangles': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 8</span>\n            <h3 class="text-lg font-bold text-slate-100">Dot Grid Rectangle Dimension Explorer</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-teal-500/20 text-teal-300 font-semibold border border-teal-500/30">Opposite Equal Sides</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Adjust width and height sliders to construct rectangles on the coordinate dot grid and observe opposite equal lengths!\n    </p>\n\n    <!-- Grid Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="rectGridSvg" viewBox="0 0 360 190" class="w-full max-w-[420px] h-44 bg-slate-900 rounded-lg shadow-inner">\n            <!-- Dot Matrix Background -->\n            <defs>\n                <pattern id="matrixPattern" width="30" height="30" patternUnits="userSpaceOnUse">\n                    <circle cx="15" cy="15" r="2" fill="#475569"/>\n                </pattern>\n            </defs>\n            <rect width="360" height="190" fill="url(#matrixPattern)" />\n\n            <!-- Dynamic Rectangle -->\n            <rect id="dynRect" x="60" y="30" width="150" height="90" fill="rgba(20, 184, 166, 0.2)" stroke="#14b8a6" stroke-width="3" rx="2" class="transition-all duration-200"/>\n\n            <!-- Dimension Lines & Text -->\n            <text id="topLenTxt" x="135" y="24" fill="#2dd4bf" font-size="11" font-weight="bold" text-anchor="middle">Top: 5 Units</text>\n            <text id="botLenTxt" x="135" y="135" fill="#2dd4bf" font-size="11" font-weight="bold" text-anchor="middle">Bottom: 5 Units</text>\n            <text id="leftLenTxt" x="42" y="80" fill="#2dd4bf" font-size="11" font-weight="bold" text-anchor="middle">Left: 3</text>\n            <text id="rightLenTxt" x="225" y="80" fill="#2dd4bf" font-size="11" font-weight="bold" text-anchor="middle">Right: 3</text>\n        </svg>\n\n        <div id="rectPropsBanner" class="mt-2 text-xs text-teal-300 font-semibold bg-teal-950/40 px-3 py-1.5 rounded-lg border border-teal-800/40 text-center w-full font-mono">\n            📏 Width = 5 Units | Height = 3 Units | Opposite Sides: Top = Bottom (5), Left = Right (3)\n        </div>\n    </div>\n\n    <!-- Sliders -->\n    <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">\n        <div class="space-y-1">\n            <div class="flex justify-between text-xs font-mono">\n                <span class="text-slate-400">Horizontal Width:</span>\n                <span id="rectWidthLbl" class="text-teal-400 font-bold">5 Units</span>\n            </div>\n            <input type="range" min="2" max="8" value="5" id="rectWidthRange" oninput="updateDynRect()" class="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-teal-500">\n        </div>\n\n        <div class="space-y-1">\n            <div class="flex justify-between text-xs font-mono">\n                <span class="text-slate-400">Vertical Height:</span>\n                <span id="rectHeightLbl" class="text-teal-400 font-bold">3 Units</span>\n            </div>\n            <input type="range" min="2" max="4" value="3" id="rectHeightRange" oninput="updateDynRect()" class="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-teal-500">\n        </div>\n    </div>\n</div>\n\n<script>\nwindow.updateDynRect = function() {\n    const wInput = document.getElementById(\'rectWidthRange\');\n    const hInput = document.getElementById(\'rectHeightRange\');\n    const wLbl = document.getElementById(\'rectWidthLbl\');\n    const hLbl = document.getElementById(\'rectHeightLbl\');\n    const rect = document.getElementById(\'dynRect\');\n    const topT = document.getElementById(\'topLenTxt\');\n    const botT = document.getElementById(\'botLenTxt\');\n    const leftT = document.getElementById(\'leftLenTxt\');\n    const rightT = document.getElementById(\'rightLenTxt\');\n    const banner = document.getElementById(\'rectPropsBanner\');\n\n    if (!wInput || !hInput || !rect) return;\n\n    const w = parseInt(wInput.value);\n    const h = parseInt(hInput.value);\n    const pixelW = w * 30;\n    const pixelH = h * 30;\n\n    wLbl.innerText = w + " Units";\n    hLbl.innerText = h + " Units";\n\n    rect.setAttribute(\'width\', pixelW.toString());\n    rect.setAttribute(\'height\', pixelH.toString());\n\n    if (topT) {\n        topT.setAttribute(\'x\', (60 + pixelW / 2).toString());\n        topT.innerText = "Top: " + w + " Units";\n    }\n    if (botT) {\n        botT.setAttribute(\'x\', (60 + pixelW / 2).toString());\n        botT.setAttribute(\'y\', (30 + pixelH + 15).toString());\n        botT.innerText = "Bottom: " + w + " Units";\n    }\n    if (leftT) {\n        leftT.setAttribute(\'y\', (30 + pixelH / 2).toString());\n        leftT.innerText = "Left: " + h;\n    }\n    if (rightT) {\n        rightT.setAttribute(\'x\', (60 + pixelW + 15).toString());\n        rightT.setAttribute(\'y\', (30 + pixelH / 2).toString());\n        rightT.innerText = "Right: " + h;\n    }\n\n    if (banner) {\n        if (w === h) {\n            banner.innerText = "⭐ Special Case: All 4 Sides Equal (" + w + " × " + h + ") — This is a Square!";\n        } else {\n            banner.innerText = "📏 Width = " + w + " | Height = " + h + " | Opposite Sides Equal (Top=Bottom=" + w + ", Left=Right=" + h + ")";\n        }\n    }\n};\n</script>\n',
    'sim_counting_nested_rectangles': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 9</span>\n            <h3 class="text-lg font-bold text-slate-100">Counting Nested Rectangles</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-violet-500/20 text-violet-300 font-semibold border border-violet-500/30">Systematic Counting</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Click the category buttons below to highlight individual panes, merged pairs, and the grand outer frame to find all 9 rectangles!\n    </p>\n\n    <!-- Window Visualizer Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="nestedRectSvg" viewBox="0 0 360 180" class="w-full max-w-[420px] h-44 bg-slate-900 rounded-lg shadow-inner">\n            <!-- 2x2 Grid Window -->\n            <!-- Pane 1 (Top-Left) -->\n            <rect id="pane1" x="90" y="20" width="85" height="65" fill="#1e293b" stroke="#64748b" stroke-width="2" class="transition-all duration-300"/>\n            <text x="132" y="58" fill="#94a3b8" font-size="12" font-weight="bold" text-anchor="middle">1</text>\n\n            <!-- Pane 2 (Top-Right) -->\n            <rect id="pane2" x="185" y="20" width="85" height="65" fill="#1e293b" stroke="#64748b" stroke-width="2" class="transition-all duration-300"/>\n            <text x="227" y="58" fill="#94a3b8" font-size="12" font-weight="bold" text-anchor="middle">2</text>\n\n            <!-- Pane 3 (Bottom-Left) -->\n            <rect id="pane3" x="90" y="95" width="85" height="65" fill="#1e293b" stroke="#64748b" stroke-width="2" class="transition-all duration-300"/>\n            <text x="132" y="133" fill="#94a3b8" font-size="12" font-weight="bold" text-anchor="middle">3</text>\n\n            <!-- Pane 4 (Bottom-Right) -->\n            <rect id="pane4" x="185" y="95" width="85" height="65" fill="#1e293b" stroke="#64748b" stroke-width="2" class="transition-all duration-300"/>\n            <text x="227" y="133" fill="#94a3b8" font-size="12" font-weight="bold" text-anchor="middle">4</text>\n\n            <!-- Overlay Highlight Box -->\n            <rect id="nestedHighlight" x="90" y="20" width="180" height="140" fill="none" stroke="#f59e0b" stroke-width="4" stroke-dasharray="0" class="transition-all duration-300 opacity-0"/>\n        </svg>\n\n        <div id="nestedCountBanner" class="mt-2 text-xs text-violet-300 font-semibold bg-violet-950/40 px-3 py-1.5 rounded-lg border border-violet-800/40 text-center w-full font-mono">\n            🔍 Total Rectangles: 4 Single + 2 Horizontal Pairs + 2 Vertical Pairs + 1 Outer Frame = 9 Rectangles\n        </div>\n    </div>\n\n    <!-- Category Buttons -->\n    <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 pt-1">\n        <button onclick="highlightNestedRect(\'single\')" class="px-2.5 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-lg text-xs font-bold transition">\n            1. Single (4)\n        </button>\n        <button onclick="highlightNestedRect(\'horiz\')" class="px-2.5 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-lg text-xs font-bold transition">\n            2. Horiz Pairs (2)\n        </button>\n        <button onclick="highlightNestedRect(\'vert\')" class="px-2.5 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-lg text-xs font-bold transition">\n            3. Vert Pairs (2)\n        </button>\n        <button onclick="highlightNestedRect(\'outer\')" class="px-2.5 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-lg text-xs font-bold transition">\n            4. Outer (1)\n        </button>\n    </div>\n</div>\n\n<script>\nwindow.highlightNestedRect = function(type) {\n    const hl = document.getElementById(\'nestedHighlight\');\n    const banner = document.getElementById(\'nestedCountBanner\');\n    if (!hl || !banner) return;\n\n    hl.style.opacity = \'1\';\n\n    if (type === \'single\') {\n        hl.setAttribute(\'x\', \'90\');\n        hl.setAttribute(\'y\', \'20\');\n        hl.setAttribute(\'width\', \'85\');\n        hl.setAttribute(\'height\', \'65\');\n        hl.setAttribute(\'stroke\', \'#3b82f6\');\n        banner.innerText = "🔍 Single Unit Panes: Exactly 4 individual rectangular panes (Pane 1, 2, 3, and 4).";\n    } else if (type === \'horiz\') {\n        hl.setAttribute(\'x\', \'90\');\n        hl.setAttribute(\'y\', \'20\');\n        hl.setAttribute(\'width\', \'180\');\n        hl.setAttribute(\'height\', \'65\');\n        hl.setAttribute(\'stroke\', \'#10b981\');\n        banner.innerText = "🔍 Horizontal Combined Pairs: Exactly 2 wide rectangles (Top: 1+2, Bottom: 3+4).";\n    } else if (type === \'vert\') {\n        hl.setAttribute(\'x\', \'90\');\n        hl.setAttribute(\'y\', \'20\');\n        hl.setAttribute(\'width\', \'85\');\n        hl.setAttribute(\'height\', \'140\');\n        hl.setAttribute(\'stroke\', \'#a855f7\');\n        banner.innerText = "🔍 Vertical Combined Pairs: Exactly 2 tall rectangles (Left: 1+3, Right: 2+4).";\n    } else if (type === \'outer\') {\n        hl.setAttribute(\'x\', \'90\');\n        hl.setAttribute(\'y\', \'20\');\n        hl.setAttribute(\'width\', \'180\');\n        hl.setAttribute(\'height\', \'140\');\n        hl.setAttribute(\'stroke\', \'#f59e0b\');\n        banner.innerText = "🔍 Master Outer Frame: Exactly 1 large overarching rectangle enclosing the whole window.";\n    }\n};\n</script>\n',
    'sim_squares_versus_rectangles': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 10</span>\n            <h3 class="text-lg font-bold text-slate-100">Square vs Rectangle Inspector</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-blue-500/20 text-blue-300 font-semibold border border-blue-500/30">Geometric Rule Test</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Adjust side lengths to see when a quadrilateral qualifies as a square, a rectangle, or both!\n    </p>\n\n    <!-- Visualizer Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="sqVsRectSvg" viewBox="0 0 360 170" class="w-full max-w-[420px] h-44 bg-slate-900 rounded-lg shadow-inner">\n            <rect id="compShape" x="80" y="30" width="120" height="120" fill="rgba(59, 130, 246, 0.2)" stroke="#3b82f6" stroke-width="3" rx="2" class="transition-all duration-200"/>\n\n            <!-- Right Angle Markers -->\n            <path d="M 80 42 L 92 42 L 92 30" fill="none" stroke="#94a3b8" stroke-width="1.5"/>\n            <path d="M 188 30 L 188 42 L 200 42" id="cornerTopRight" fill="none" stroke="#94a3b8" stroke-width="1.5"/>\n\n            <!-- Dimension Text -->\n            <text id="compWidthTxt" x="140" y="22" fill="#60a5fa" font-size="11" font-weight="bold" text-anchor="middle">Width = 4 cm</text>\n            <text id="compHeightTxt" x="65" y="95" fill="#60a5fa" font-size="11" font-weight="bold" text-anchor="middle">4 cm</text>\n        </svg>\n\n        <div id="compResultNotice" class="mt-2 text-xs text-blue-300 font-semibold bg-blue-950/40 px-3 py-1.5 rounded-lg border border-blue-800/40 text-center w-full font-mono">\n            ⭐ Width = 4 cm, Height = 4 cm: All 4 sides equal! This shape is BOTH a Square AND a Rectangle.\n        </div>\n    </div>\n\n    <!-- Quick Switcher -->\n    <div class="grid grid-cols-2 gap-3 pt-1">\n        <button onclick="setCompShape(4, 4)" class="px-3 py-2 bg-blue-600 hover:bg-blue-500 rounded-xl text-xs font-bold transition">\n            ■ Make Square (4 cm × 4 cm)\n        </button>\n        <button onclick="setCompShape(7, 4)" class="px-3 py-2 bg-indigo-600 hover:bg-indigo-500 rounded-xl text-xs font-bold transition">\n            ▬ Make Rectangle (7 cm × 4 cm)\n        </button>\n    </div>\n</div>\n\n<script>\nwindow.setCompShape = function(wUnits, hUnits) {\n    const shape = document.getElementById(\'compShape\');\n    const wTxt = document.getElementById(\'compWidthTxt\');\n    const hTxt = document.getElementById(\'compHeightTxt\');\n    const cTR = document.getElementById(\'cornerTopRight\');\n    const notice = document.getElementById(\'compResultNotice\');\n\n    if (!shape) return;\n\n    const pxW = wUnits * 25;\n    const pxH = hUnits * 25;\n\n    shape.setAttribute(\'width\', pxW.toString());\n    shape.setAttribute(\'height\', pxH.toString());\n\n    if (wTxt) {\n        wTxt.setAttribute(\'x\', (80 + pxW / 2).toString());\n        wTxt.innerText = "Width = " + wUnits + " cm";\n    }\n    if (hTxt) {\n        hTxt.setAttribute(\'y\', (30 + pxH / 2).toString());\n        hTxt.innerText = hUnits + " cm";\n    }\n    if (cTR) {\n        cTR.setAttribute(\'d\', "M " + (80 + pxW - 12) + " 30 L " + (80 + pxW - 12) + " 42 L " + (80 + pxW) + " 42");\n    }\n\n    if (notice) {\n        if (wUnits === hUnits) {\n            shape.setAttribute(\'fill\', \'rgba(59, 130, 246, 0.2)\');\n            shape.setAttribute(\'stroke\', \'#3b82f6\');\n            notice.innerText = "⭐ Width = " + wUnits + " cm, Height = " + hUnits + " cm: All 4 sides equal! This is a Square (and a special Rectangle).";\n        } else {\n            shape.setAttribute(\'fill\', \'rgba(168, 85, 247, 0.2)\');\n            shape.setAttribute(\'stroke\', \'#a855f7\');\n            notice.innerText = "📐 Width = " + wUnits + " cm, Height = " + hUnits + " cm: Opposite sides equal! This is a Rectangle, NOT a square.";\n        }\n    }\n};\n</script>\n',
    'sim_matchstick_shape_tiling': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 11</span>\n            <h3 class="text-lg font-bold text-slate-100">Matchstick Shape & Shared Seam Tiling</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-amber-500/20 text-amber-300 font-semibold border border-amber-500/30">Shared Boundary Walls</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Construct connected squares and triangles using wooden matchsticks to see how shared boundary walls save sticks!\n    </p>\n\n    <!-- Matchstick Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="matchstickSvg" viewBox="0 0 360 170" class="w-full max-w-[420px] h-44 bg-slate-900 rounded-lg shadow-inner">\n            <g id="matchstickDrawGroup">\n                <!-- 2 Connected Squares (Default) -->\n                <!-- Outer Sticks (Cyan) -->\n                <line x1="90" y1="45" x2="160" y2="45" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n                <line x1="160" y1="45" x2="230" y2="45" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n                <line x1="90" y1="115" x2="160" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n                <line x1="160" y1="115" x2="230" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n                <line x1="90" y1="45" x2="90" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n                <line x1="230" y1="45" x2="230" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n\n                <!-- Shared Middle Wall (Gold) -->\n                <line x1="160" y1="45" x2="160" y2="115" stroke="#f59e0b" stroke-width="6" stroke-linecap="round"/>\n\n                <!-- Labels -->\n                <text x="125" y="85" fill="#38bdf8" font-size="11" font-weight="bold" text-anchor="middle">Square 1</text>\n                <text x="195" y="85" fill="#38bdf8" font-size="11" font-weight="bold" text-anchor="middle">Square 2</text>\n                <text x="160" y="32" fill="#fbbf24" font-size="10" font-weight="bold" text-anchor="middle">Shared Wall ⭐</text>\n            </g>\n        </svg>\n\n        <div id="matchstickStatus" class="mt-2 text-xs text-amber-300 font-semibold bg-amber-950/40 px-3 py-1.5 rounded-lg border border-amber-800/40 text-center w-full font-mono">\n            🪵 2 Connected Squares: 7 Matchsticks (6 Outer + 1 Shared Wall). Saved 1 stick!\n        </div>\n    </div>\n\n    <!-- Configuration Buttons -->\n    <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 pt-1">\n        <button onclick="setMatchstickModel(\'sq1\')" class="px-2 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-lg text-xs font-bold transition">\n            1 Square (4)\n        </button>\n        <button onclick="setMatchstickModel(\'sq2\')" class="px-2 py-1.5 bg-amber-600 hover:bg-amber-500 text-white rounded-lg text-xs font-bold transition">\n            2 Squares (7)\n        </button>\n        <button onclick="setMatchstickModel(\'sq3\')" class="px-2 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-lg text-xs font-bold transition">\n            3 Squares (10)\n        </button>\n        <button onclick="setMatchstickModel(\'tri2\')" class="px-2 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-lg text-xs font-bold transition">\n            2 Triangles (5)\n        </button>\n    </div>\n</div>\n\n<script>\nwindow.setMatchstickModel = function(model) {\n    const grp = document.getElementById(\'matchstickDrawGroup\');\n    const st = document.getElementById(\'matchstickStatus\');\n    if (!grp) return;\n\n    if (model === \'sq1\') {\n        grp.innerHTML = `\n            <line x1="135" y1="45" x2="205" y2="45" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="135" y1="115" x2="205" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="135" y1="45" x2="135" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="205" y1="45" x2="205" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <text x="170" y="85" fill="#38bdf8" font-size="11" font-weight="bold" text-anchor="middle">Single Square</text>\n        `;\n        st.innerText = "🪵 1 Standalone Square: Exactly 4 matchsticks needed (4 boundary edges).";\n    } else if (model === \'sq2\') {\n        grp.innerHTML = `\n            <line x1="90" y1="45" x2="160" y2="45" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="160" y1="45" x2="230" y2="45" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="90" y1="115" x2="160" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="160" y1="115" x2="230" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="90" y1="45" x2="90" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="230" y1="45" x2="230" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="160" y1="45" x2="160" y2="115" stroke="#f59e0b" stroke-width="6" stroke-linecap="round"/>\n            <text x="125" y="85" fill="#38bdf8" font-size="11" font-weight="bold" text-anchor="middle">Square 1</text>\n            <text x="195" y="85" fill="#38bdf8" font-size="11" font-weight="bold" text-anchor="middle">Square 2</text>\n            <text x="160" y="32" fill="#fbbf24" font-size="10" font-weight="bold" text-anchor="middle">Shared Wall ⭐</text>\n        `;\n        st.innerText = "🪵 2 Connected Squares: 7 Matchsticks (4 + 3). The 1 shared wall saves a matchstick!";\n    } else if (model === \'sq3\') {\n        grp.innerHTML = `\n            <line x1="60" y1="45" x2="130" y2="45" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="130" y1="45" x2="200" y2="45" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="200" y1="45" x2="270" y2="45" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="60" y1="115" x2="130" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="130" y1="115" x2="200" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="200" y1="115" x2="270" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="60" y1="45" x2="60" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="270" y1="45" x2="270" y2="115" stroke="#06b6d4" stroke-width="4" stroke-linecap="round"/>\n            <line x1="130" y1="45" x2="130" y2="115" stroke="#f59e0b" stroke-width="5" stroke-linecap="round"/>\n            <line x1="200" y1="45" x2="200" y2="115" stroke="#f59e0b" stroke-width="5" stroke-linecap="round"/>\n            <text x="95" y="85" fill="#38bdf8" font-size="10" font-weight="bold" text-anchor="middle">Sq 1</text>\n            <text x="165" y="85" fill="#38bdf8" font-size="10" font-weight="bold" text-anchor="middle">Sq 2</text>\n            <text x="235" y="85" fill="#38bdf8" font-size="10" font-weight="bold" text-anchor="middle">Sq 3</text>\n        `;\n        st.innerText = "🪵 3 Connected Squares: 10 Matchsticks (4 + 3 + 3). Two shared walls save 2 sticks!";\n    } else if (model === \'tri2\') {\n        grp.innerHTML = `\n            <line x1="180" y1="25" x2="120" y2="135" stroke="#10b981" stroke-width="4" stroke-linecap="round"/>\n            <line x1="180" y1="25" x2="240" y2="135" stroke="#10b981" stroke-width="4" stroke-linecap="round"/>\n            <line x1="120" y1="135" x2="180" y2="135" stroke="#10b981" stroke-width="4" stroke-linecap="round"/>\n            <line x1="180" y1="135" x2="240" y2="135" stroke="#10b981" stroke-width="4" stroke-linecap="round"/>\n            <line x1="180" y1="25" x2="180" y2="135" stroke="#f59e0b" stroke-width="5" stroke-linecap="round"/>\n            <text x="150" y="105" fill="#34d399" font-size="10" font-weight="bold" text-anchor="middle">Tri 1</text>\n            <text x="210" y="105" fill="#34d399" font-size="10" font-weight="bold" text-anchor="middle">Tri 2</text>\n            <text x="180" y="155" fill="#fbbf24" font-size="10" font-weight="bold" text-anchor="middle">Shared Center Seam (5 sticks total)</text>\n        `;\n        st.innerText = "🪵 2 Connected Triangles: 5 Matchsticks total (3 + 2). Shared center spine saves 1 stick!";\n    }\n};\n</script>\n',
    'sim_square_corner_angles': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 12</span>\n            <h3 class="text-lg font-bold text-slate-100">Square Corner Angle Tester</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-emerald-500/20 text-emerald-300 font-semibold border border-emerald-500/30">90° Right Angle Tester</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Place the folded paper corner tester against various angles to classify them as equal to, less than, or greater than a square corner!\n    </p>\n\n    <!-- Angle Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="angleTesterSvg" viewBox="0 0 360 170" class="w-full max-w-[420px] h-44 bg-slate-900 rounded-lg shadow-inner">\n            <!-- Test Angle Rays -->\n            <line x1="160" y1="130" x2="280" y2="130" stroke="#94a3b8" stroke-width="4" stroke-linecap="round"/>\n            <line id="testRaySlant" x1="160" y1="130" x2="160" y2="20" stroke="#94a3b8" stroke-width="4" stroke-linecap="round" class="transition-all duration-300"/>\n\n            <!-- Folded Paper 90-degree Tester Overlay -->\n            <polygon points="160,130 160,50 240,130" fill="rgba(245, 158, 11, 0.25)" stroke="#f59e0b" stroke-width="2" stroke-dasharray="3 3"/>\n            <text x="180" y="105" fill="#fbbf24" font-size="10" font-weight="bold">Paper Tester (90°)</text>\n\n            <!-- Angle Arc -->\n            <path id="angleArc" d="M 190 130 A 30 30 0 0 0 160 100" fill="none" stroke="#10b981" stroke-width="3"/>\n\n            <circle cx="160" cy="130" r="5" fill="#f59e0b"/>\n        </svg>\n\n        <div id="angleClassification" class="mt-2 text-xs text-emerald-300 font-semibold bg-emerald-950/40 px-3 py-1.5 rounded-lg border border-emerald-800/40 text-center w-full font-mono">\n            📐 Perfect Fit: Exactly EQUAL to a Square Corner (90° Right Angle).\n        </div>\n    </div>\n\n    <!-- Tester Buttons -->\n    <div class="grid grid-cols-3 gap-2 pt-1">\n        <button onclick="setTestAngle(\'equal\')" class="px-3 py-2 bg-emerald-600 hover:bg-emerald-500 rounded-xl text-xs font-bold transition">\n            1. Equal (90° Book Corner)\n        </button>\n        <button onclick="setTestAngle(\'less\')" class="px-3 py-2 bg-blue-600 hover:bg-blue-500 rounded-xl text-xs font-bold transition">\n            2. Less Than (Scissors 45°)\n        </button>\n        <button onclick="setTestAngle(\'greater\')" class="px-3 py-2 bg-amber-600 hover:bg-amber-500 rounded-xl text-xs font-bold transition">\n            3. Greater Than (Clock 130°)\n        </button>\n    </div>\n</div>\n\n<script>\nwindow.setTestAngle = function(type) {\n    const ray = document.getElementById(\'testRaySlant\');\n    const arc = document.getElementById(\'angleArc\');\n    const cls = document.getElementById(\'angleClassification\');\n    if (!ray) return;\n\n    if (type === \'equal\') {\n        ray.setAttribute(\'x2\', \'160\');\n        ray.setAttribute(\'y2\', \'20\');\n        if (arc) arc.setAttribute(\'d\', \'M 190 130 A 30 30 0 0 0 160 100\');\n        cls.innerText = "📐 Perfect Fit: Exactly EQUAL to a Square Corner (Book cover, doorway, picture frame).";\n    } else if (type === \'less\') {\n        ray.setAttribute(\'x2\', \'230\');\n        ray.setAttribute(\'y2\', \'55\');\n        if (arc) arc.setAttribute(\'d\', \'M 190 130 A 30 30 0 0 0 185 105\');\n        cls.innerText = "✂️ Narrow Opening: LESS than a Square Corner (Acute angle, scissor tips, samosa points).";\n    } else if (type === \'greater\') {\n        ray.setAttribute(\'x2\', \'80\');\n        ray.setAttribute(\'y2\', \'60\');\n        if (arc) arc.setAttribute(\'d\', \'M 190 130 A 30 30 0 0 0 135 110\');\n        cls.innerText = "🛋️ Wide Opening: GREATER than a Square Corner (Obtuse angle, reclining chair, clock at 4 o\'clock).";\n    }\n};\n</script>\n',
    'sim_triangle_pattern_counts': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 13</span>\n            <h3 class="text-lg font-bold text-slate-100">Nested Triangle Pattern Counter</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-teal-500/20 text-teal-300 font-semibold border border-teal-500/30">Scale-Tiered Counting</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Count triangles systematically by size across this geometric star: single small units, composite groups, and the grand master triangle!\n    </p>\n\n    <!-- Star Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="triCountSvg" viewBox="0 0 360 180" class="w-full max-w-[420px] h-44 bg-slate-900 rounded-lg shadow-inner">\n            <!-- Master Triangle -->\n            <polygon id="masterTri" points="180,20 100,160 260,160" fill="rgba(20, 184, 166, 0.1)" stroke="#0d9488" stroke-width="2"/>\n\n            <!-- Internal Sub-Triangles -->\n            <!-- Top Unit 1 -->\n            <polygon id="unitTri1" points="180,20 140,90 220,90" fill="rgba(59, 130, 246, 0.2)" stroke="#3b82f6" stroke-width="2"/>\n            <text x="180" y="65" fill="#93c5fd" font-size="11" font-weight="bold" text-anchor="middle">1</text>\n\n            <!-- Bottom Left Unit 2 -->\n            <polygon id="unitTri2" points="140,90 100,160 180,160" fill="rgba(59, 130, 246, 0.2)" stroke="#3b82f6" stroke-width="2"/>\n            <text x="140" y="135" fill="#93c5fd" font-size="11" font-weight="bold" text-anchor="middle">2</text>\n\n            <!-- Bottom Right Unit 3 -->\n            <polygon id="unitTri3" points="220,90 180,160 260,160" fill="rgba(59, 130, 246, 0.2)" stroke="#3b82f6" stroke-width="2"/>\n            <text x="220" y="135" fill="#93c5fd" font-size="11" font-weight="bold" text-anchor="middle">3</text>\n\n            <!-- Center Inverted Unit 4 -->\n            <polygon id="unitTri4" points="140,90 220,90 180,160" fill="rgba(245, 158, 11, 0.2)" stroke="#f59e0b" stroke-width="2"/>\n            <text x="180" y="120" fill="#fde68a" font-size="11" font-weight="bold" text-anchor="middle">4 (Inverted)</text>\n        </svg>\n\n        <div id="triCountNotice" class="mt-2 text-xs text-teal-300 font-semibold bg-teal-950/40 px-3 py-1.5 rounded-lg border border-teal-800/40 text-center w-full font-mono">\n            🔺 Total Triangles = 4 Small Units (3 upright + 1 inverted) + 1 Grand Master Triangle = 5 Triangles\n        </div>\n    </div>\n\n    <!-- Tier Buttons -->\n    <div class="grid grid-cols-3 gap-2 pt-1">\n        <button onclick="highlightTriTier(\'units\')" class="px-3 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-xl text-xs font-bold transition">\n            1. Small Units (4)\n        </button>\n        <button onclick="highlightTriTier(\'master\')" class="px-3 py-2 bg-teal-600 hover:bg-teal-500 rounded-xl text-xs font-bold transition">\n            2. Grand Master (1)\n        </button>\n        <button onclick="highlightTriTier(\'all\')" class="px-3 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-xl text-xs font-bold transition">\n            3. Show All (5)\n        </button>\n    </div>\n</div>\n\n<script>\nwindow.highlightTriTier = function(tier) {\n    const notice = document.getElementById(\'triCountNotice\');\n    const mt = document.getElementById(\'masterTri\');\n    if (!notice || !mt) return;\n\n    if (tier === \'units\') {\n        mt.setAttribute(\'stroke-width\', \'1\');\n        notice.innerText = "🔺 Small Units: 4 single-unit triangles (3 pointing upward, 1 inverted in the center).";\n    } else if (tier === \'master\') {\n        mt.setAttribute(\'stroke-width\', \'5\');\n        mt.setAttribute(\'stroke\', \'#f59e0b\');\n        notice.innerText = "⭐ Grand Master: 1 overarching triangle enclosing all four smaller unit triangles.";\n    } else {\n        mt.setAttribute(\'stroke-width\', \'2\');\n        mt.setAttribute(\'stroke\', \'#0d9488\');\n        notice.innerText = "🔺 Complete Count: 4 Small Units + 1 Grand Master Triangle = 5 Triangles in Total!";\n    }\n};\n</script>\n',
    'sim_paper_circle_center': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 14</span>\n            <h3 class="text-lg font-bold text-slate-100">Paper Plate Circle Center Discovery</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-rose-500/20 text-rose-300 font-semibold border border-rose-500/30">Crease Intersection</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Fold a circular paper disc in half twice along different directions to find its exact rotational balance center!\n    </p>\n\n    <!-- Circle Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="circleCenterSvg" viewBox="0 0 360 180" class="w-full max-w-[420px] h-44 bg-slate-900 rounded-lg shadow-inner">\n            <!-- Circular Paper Disc -->\n            <circle cx="180" cy="90" r="70" fill="rgba(244, 63, 94, 0.15)" stroke="#f43f5e" stroke-width="3"/>\n\n            <!-- Crease Line 1 (Vertical Diameter) -->\n            <line id="crease1" x1="180" y1="20" x2="180" y2="160" stroke="#fb7185" stroke-width="2.5" stroke-dasharray="4 3" class="transition-all duration-300"/>\n\n            <!-- Crease Line 2 (Horizontal Diameter) -->\n            <line id="crease2" x1="110" y1="90" x2="250" y2="90" stroke="#fb7185" stroke-width="2.5" stroke-dasharray="4 3" class="transition-all duration-300"/>\n\n            <!-- Center Intersection Dot -->\n            <circle id="centerDot" cx="180" cy="90" r="6" fill="#facc15" stroke="#eab308" stroke-width="2" class="transition-all duration-300"/>\n            <text id="centerDotLabel" x="180" y="115" fill="#fde047" font-size="11" font-weight="bold" text-anchor="middle">Center Point ⭐</text>\n        </svg>\n\n        <div id="circleCenterNotice" class="mt-2 text-xs text-rose-300 font-semibold bg-rose-950/40 px-3 py-1.5 rounded-lg border border-rose-800/40 text-center w-full font-mono">\n            🎯 Both diameter creases intersect at one single point: the exact rotational center of the circle!\n        </div>\n    </div>\n\n    <!-- Fold Actions -->\n    <div class="grid grid-cols-3 gap-2 pt-1">\n        <button onclick="setCircleFoldStep(1)" class="px-3 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-xl text-xs font-bold transition">\n            1. First Fold (Crease 1)\n        </button>\n        <button onclick="setCircleFoldStep(2)" class="px-3 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-xl text-xs font-bold transition">\n            2. Second Fold (Crease 2)\n        </button>\n        <button onclick="setCircleFoldStep(3)" class="px-3 py-2 bg-rose-600 hover:bg-rose-500 rounded-xl text-xs font-bold transition">\n            3. Intersection Center\n        </button>\n    </div>\n</div>\n\n<script>\nwindow.setCircleFoldStep = function(step) {\n    const c1 = document.getElementById(\'crease1\');\n    const c2 = document.getElementById(\'crease2\');\n    const dot = document.getElementById(\'centerDot\');\n    const lbl = document.getElementById(\'centerDotLabel\');\n    const notice = document.getElementById(\'circleCenterNotice\');\n\n    if (step === 1) {\n        if (c1) c1.style.opacity = \'1\';\n        if (c2) c2.style.opacity = \'0\';\n        if (dot) dot.style.opacity = \'0\';\n        if (lbl) lbl.style.opacity = \'0\';\n        notice.innerText = "📄 Step 1: Folding the disc in half creates Crease 1 (a straight diameter dividing circle into 2 semicircles).";\n    } else if (step === 2) {\n        if (c1) c1.style.opacity = \'1\';\n        if (c2) c2.style.opacity = \'1\';\n        if (dot) dot.style.opacity = \'0\';\n        if (lbl) lbl.style.opacity = \'0\';\n        notice.innerText = "📄 Step 2: Folding in half again in a different direction creates Crease 2 (another diameter).";\n    } else {\n        if (c1) c1.style.opacity = \'1\';\n        if (c2) c2.style.opacity = \'1\';\n        if (dot) dot.style.opacity = \'1\';\n        if (lbl) lbl.style.opacity = \'1\';\n        notice.innerText = "🎯 Step 3: Unfolding flat reveals that the two diameters intersect at the exact center point!";\n    }\n};\n</script>\n',
    'sim_polygon_side_counters': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 15</span>\n            <h3 class="text-lg font-bold text-slate-100">Polygon Side & Corner Transformer</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-cyan-500/20 text-cyan-300 font-semibold border border-cyan-500/30">Sides = Corners Law</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Slide the polygon dial from 3 to 10 sides to watch how regular polygons transform and confirm the law: Sides = Corners!\n    </p>\n\n    <!-- Polygon Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="polySvg" viewBox="0 0 360 180" class="w-full max-w-[420px] h-44 bg-slate-900 rounded-lg shadow-inner">\n            <polygon id="polyShape" points="" fill="rgba(6, 182, 212, 0.2)" stroke="#06b6d4" stroke-width="3" class="transition-all duration-300"/>\n            <text id="polyNameTxt" x="180" y="100" fill="#22d3ee" font-size="14" font-weight="bold" text-anchor="middle">Hexagon</text>\n        </svg>\n\n        <div id="polyStatsBanner" class="mt-2 text-xs text-cyan-300 font-semibold bg-cyan-950/40 px-3 py-1.5 rounded-lg border border-cyan-800/40 text-center w-full font-mono">\n            🔷 Hexagon: 6 Straight Sides = 6 Sharp Corners (Honeycomb Cell)\n        </div>\n    </div>\n\n    <!-- Slider -->\n    <div class="space-y-2 pt-1">\n        <div class="flex justify-between text-xs font-mono">\n            <span class="text-slate-400">Number of Sides & Corners:</span>\n            <span id="polyDialLabel" class="text-cyan-400 font-bold">6 Sides (Hexagon)</span>\n        </div>\n        <input type="range" min="3" max="10" value="6" id="polyDialRange" oninput="updatePolygonDial(this.value)" class="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-cyan-500">\n        <div class="flex justify-between text-[11px] text-slate-500 font-mono">\n            <span>3 (Triangle)</span>\n            <span>5 (Pentagon)</span>\n            <span>8 (Octagon)</span>\n            <span>10 (Decagon)</span>\n        </div>\n    </div>\n</div>\n\n<script>\nwindow.polyNames = {\n    3: { name: "Triangle", desc: "3 Straight Sides = 3 Corners (Samosa, traffic warning sign)" },\n    4: { name: "Quadrilateral (Square)", desc: "4 Straight Sides = 4 Corners (Chessboard tile)" },\n    5: { name: "Pentagon", desc: "5 Straight Sides = 5 Corners (Signpost, school banner)" },\n    6: { name: "Hexagon", desc: "6 Straight Sides = 6 Corners (Bee honeycomb cell, pencil cross-section)" },\n    7: { name: "Heptagon", desc: "7 Straight Sides = 7 Corners (Decorative palace tile)" },\n    8: { name: "Octagon", desc: "8 Straight Sides = 8 Corners (Red road STOP sign)" },\n    9: { name: "Nonagon", desc: "9 Straight Sides = 9 Corners (9-pointed floral rangoli)" },\n    10: { name: "Decagon", desc: "10 Straight Sides = 10 Corners (Star mandala perimeter)" }\n};\n\nwindow.updatePolygonDial = function(nStr) {\n    const n = parseInt(nStr);\n    const shape = document.getElementById(\'polyShape\');\n    const nameTxt = document.getElementById(\'polyNameTxt\');\n    const banner = document.getElementById(\'polyStatsBanner\');\n    const lbl = document.getElementById(\'polyDialLabel\');\n\n    if (!shape) return;\n\n    lbl.innerText = n + " Sides (" + window.polyNames[n].name + ")";\n    nameTxt.innerText = window.polyNames[n].name;\n    banner.innerText = "🔷 " + window.polyNames[n].name + ": " + window.polyNames[n].desc;\n\n    // Calculate regular polygon points\n    const cx = 180, cy = 90, r = 65;\n    let pts = [];\n    for (let i = 0; i < n; i++) {\n        const angle = (i * 2 * Math.PI / n) - (Math.PI / 2);\n        const x = cx + r * Math.cos(angle);\n        const y = cy + r * Math.sin(angle);\n        pts.push(x.toFixed(1) + "," + y.toFixed(1));\n    }\n    shape.setAttribute(\'points\', pts.join(" "));\n};\n\n// Init\nsetTimeout(function() { if (window.updatePolygonDial) window.updatePolygonDial(6); }, 100);\n</script>\n',
    'sim_tangram_puzzle_assembly': '\n<div class="bg-slate-900 border border-slate-800 rounded-2xl p-4 sm:p-5 text-white space-y-4">\n    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800 pb-3">\n        <div>\n            <span class="text-xs font-bold uppercase tracking-wider text-amber-400">Interactive Lab 16</span>\n            <h3 class="text-lg font-bold text-slate-100">Classic 7-Piece Tangram Assembly</h3>\n        </div>\n        <div class="flex items-center gap-2">\n            <span class="text-xs px-2.5 py-1 rounded-full bg-emerald-500/20 text-emerald-300 font-semibold border border-emerald-500/30">7 Geometric Tans</span>\n        </div>\n    </div>\n    \n    <p class="text-sm text-slate-300">\n        Click presets to assemble all 7 classic tangram pieces into a square, a sailing boat, or a flying bird silhouette!\n    </p>\n\n    <!-- Tangram Stage -->\n    <div class="bg-slate-950 border border-slate-800 rounded-xl p-3 flex flex-col items-center">\n        <svg id="tangramSvg" viewBox="0 0 360 180" class="w-full max-w-[420px] h-44 bg-slate-900 rounded-lg shadow-inner">\n            <g id="tangramPiecesGroup">\n                <!-- Master Square Arrangement (Default) -->\n                <!-- Big Tri 1 (Cyan) -->\n                <polygon points="120,30 240,30 180,90" fill="#06b6d4" stroke="#0891b2" stroke-width="1.5"/>\n                <!-- Big Tri 2 (Blue) -->\n                <polygon points="120,30 120,150 180,90" fill="#3b82f6" stroke="#2563eb" stroke-width="1.5"/>\n                <!-- Medium Tri (Purple) -->\n                <polygon points="240,30 240,90 210,60" fill="#a855f7" stroke="#9333ea" stroke-width="1.5"/>\n                <!-- Small Tri 1 (Green) -->\n                <polygon points="180,90 210,60 210,120" fill="#10b981" stroke="#059669" stroke-width="1.5"/>\n                <!-- Square (Yellow) -->\n                <polygon points="210,60 240,90 210,120 180,90" fill="#facc15" stroke="#eab308" stroke-width="1.5"/>\n                <!-- Small Tri 2 (Red) -->\n                <polygon points="120,150 180,150 150,120" fill="#ef4444" stroke="#dc2626" stroke-width="1.5"/>\n                <!-- Parallelogram (Amber) -->\n                <polygon points="180,150 240,150 210,120 150,120" fill="#f59e0b" stroke="#d97706" stroke-width="1.5"/>\n            </g>\n        </svg>\n\n        <div id="tangramSilhouetteNotice" class="mt-2 text-xs text-emerald-300 font-semibold bg-emerald-950/40 px-3 py-1.5 rounded-lg border border-emerald-800/40 text-center w-full font-mono">\n            🧩 Master Square Silhouette: All 7 tans (5 Triangles + 1 Square + 1 Parallelogram) united into one master square.\n        </div>\n    </div>\n\n    <!-- Presets -->\n    <div class="grid grid-cols-3 gap-2 pt-1">\n        <button onclick="setTangramPreset(\'square\')" class="px-3 py-2 bg-emerald-600 hover:bg-emerald-500 rounded-xl text-xs font-bold transition">\n            ■ Master Square\n        </button>\n        <button onclick="setTangramPreset(\'boat\')" class="px-3 py-2 bg-blue-600 hover:bg-blue-500 rounded-xl text-xs font-bold transition">\n            ⛵ Sailing Boat\n        </button>\n        <button onclick="setTangramPreset(\'rocket\')" class="px-3 py-2 bg-purple-600 hover:bg-purple-500 rounded-xl text-xs font-bold transition">\n            🚀 Soaring Rocket\n        </button>\n    </div>\n</div>\n\n<script>\nwindow.setTangramPreset = function(preset) {\n    const grp = document.getElementById(\'tangramPiecesGroup\');\n    const notice = document.getElementById(\'tangramSilhouetteNotice\');\n    if (!grp) return;\n\n    if (preset === \'square\') {\n        grp.innerHTML = `\n            <polygon points="120,30 240,30 180,90" fill="#06b6d4" stroke="#0891b2" stroke-width="1.5"/>\n            <polygon points="120,30 120,150 180,90" fill="#3b82f6" stroke="#2563eb" stroke-width="1.5"/>\n            <polygon points="240,30 240,90 210,60" fill="#a855f7" stroke="#9333ea" stroke-width="1.5"/>\n            <polygon points="180,90 210,60 210,120" fill="#10b981" stroke="#059669" stroke-width="1.5"/>\n            <polygon points="210,60 240,90 210,120 180,90" fill="#facc15" stroke="#eab308" stroke-width="1.5"/>\n            <polygon points="120,150 180,150 150,120" fill="#ef4444" stroke="#dc2626" stroke-width="1.5"/>\n            <polygon points="180,150 240,150 210,120 150,120" fill="#f59e0b" stroke="#d97706" stroke-width="1.5"/>\n        `;\n        notice.innerText = "🧩 Master Square Silhouette: All 7 pieces perfectly fit inside the original dissection square!";\n    } else if (preset === \'boat\') {\n        grp.innerHTML = `\n            <polygon points="180,20 180,90 250,90" fill="#06b6d4" stroke="#0891b2" stroke-width="1.5"/>\n            <polygon points="170,35 170,90 120,90" fill="#3b82f6" stroke="#2563eb" stroke-width="1.5"/>\n            <polygon points="180,90 210,90 195,110" fill="#10b981" stroke="#059669" stroke-width="1.5"/>\n            <polygon points="70,110 290,110 250,150 110,150" fill="#f59e0b" stroke="#d97706" stroke-width="1.5"/>\n            <polygon points="130,110 160,110 160,135 130,135" fill="#facc15" stroke="#eab308" stroke-width="1.5"/>\n        `;\n        notice.innerText = "⛵ Sailing Boat Silhouette: 7 tans rearranged to form tall billowing sails and a floating hull!";\n    } else if (preset === \'rocket\') {\n        grp.innerHTML = `\n            <polygon points="180,15 150,55 210,55" fill="#ef4444" stroke="#dc2626" stroke-width="1.5"/>\n            <polygon points="150,55 210,55 210,105 150,105" fill="#3b82f6" stroke="#2563eb" stroke-width="1.5"/>\n            <polygon points="150,105 180,105 165,130" fill="#10b981" stroke="#059669" stroke-width="1.5"/>\n            <polygon points="180,105 210,105 195,130" fill="#06b6d4" stroke="#0891b2" stroke-width="1.5"/>\n            <polygon points="150,70 120,120 150,105" fill="#f59e0b" stroke="#d97706" stroke-width="1.5"/>\n            <polygon points="210,70 240,120 210,105" fill="#a855f7" stroke="#9333ea" stroke-width="1.5"/>\n        `;\n        notice.innerText = "🚀 Soaring Rocket Silhouette: Dissection tans transformed into an aerodynamic space cruiser!";\n    }\n};\n</script>\n',
}
